#include "retarget_core.h"
#include "rig_bind.h" /* generated by tools/build_bridge.py from the lab's jimmy-bind.json */
#include <math.h>
#include <string.h>

/* Gothic bone -> rig joint and the rig child that aims it (-1: none). */
static const struct { const char* name; int joint, child; } MAPPING[] = {
    {"BIP01 PELVIS", 1, 2}, {"BIP01 SPINE", 2, 9}, {"BIP01 SPINE1", 9, 10}, {"BIP01 SPINE2", 10, 11},
    {"BIP01 NECK", 11, 12}, {"BIP01 HEAD", 12, -1},
    {"BIP01 L CLAVICLE", 19, 20}, {"BIP01 L UPPERARM", 20, 21}, {"BIP01 L FOREARM", 21, 22}, {"BIP01 L HAND", 22, -1},
    {"BIP01 R CLAVICLE", 27, 28}, {"BIP01 R UPPERARM", 28, 29}, {"BIP01 R FOREARM", 29, 30}, {"BIP01 R HAND", 30, -1},
    {"BIP01 L THIGH", 3, 4}, {"BIP01 L CALF", 4, 5}, {"BIP01 L FOOT", 5, -1},
    {"BIP01 R THIGH", 6, 7}, {"BIP01 R CALF", 7, 8}, {"BIP01 R FOOT", 8, -1},
};
/* Gothic's spine segments are distributed unlike the rig's, so each Gothic
   spine joint goes to the same fraction along the rig's pelvis-to-neck curve. */
static const char* const SPINE_CHAIN[5] = {"BIP01 PELVIS", "BIP01 SPINE", "BIP01 SPINE1", "BIP01 SPINE2", "BIP01 NECK"};
static const int RIG_SPINE[5] = {1, 2, 9, 10, 11};
static const char* const LEG_NAMES[2][3] = {{"BIP01 L THIGH", "BIP01 L CALF", "BIP01 L FOOT"}, {"BIP01 R THIGH", "BIP01 R CALF", "BIP01 R FOOT"}};
static const int LEG_RIG[2][2] = {{5, 4}, {8, 7}}; /* foot target, knee hint */

static void mul(const float* a, const float* b, float* out) {
    float r[9];
    for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j) r[i * 3 + j] = a[i * 3] * b[j] + a[i * 3 + 1] * b[3 + j] + a[i * 3 + 2] * b[6 + j];
    memcpy(out, r, sizeof(r));
}
static void mul_vec(const float* a, const float* v, float* out) {
    float r[3];
    for (int i = 0; i < 3; ++i) r[i] = a[i * 3] * v[0] + a[i * 3 + 1] * v[1] + a[i * 3 + 2] * v[2];
    memcpy(out, r, sizeof(r));
}
static void transpose(const float* a, float* out) {
    float r[9];
    for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j) r[i * 3 + j] = a[j * 3 + i];
    memcpy(out, r, sizeof(r));
}

int retarget_input_valid(const float (*pose)[13], const float board_position[3]) {
    for (int i = 0; i < RETARGET_RIG_BONES; ++i) {
        for (int k = 0; k < 12; ++k) if (!isfinite(pose[i][k])) return 0;
        float distance2 = 0;
        for (int k = 0; k < 3; ++k) {
            if (!isfinite(board_position[k])) return 0;
            float d = pose[i][9 + k] - board_position[k];
            distance2 += d * d;
            const float* r = pose[i] + k * 3;
            float norm = r[0] * r[0] + r[1] * r[1] + r[2] * r[2];
            if (norm < .5f || norm > 1.5f) return 0;
            for (int j = 0; j < k; ++j) {
                const float* s = pose[i] + j * 3;
                if (fabsf(r[0] * s[0] + r[1] * s[1] + r[2] * s[2]) > .25f) return 0;
            }
        }
        if (distance2 > 16) return 0; /* every joint within 4 m of the board */
    }
    return 1;
}

int retarget_locals_valid(int count, const float (*local)[16]) {
    if (count < 1 || count > RETARGET_MAX_NODES) return 0;
    for (int i = 0; i < count; ++i) {
        for (int k = 0; k < 16; ++k) if (!isfinite(local[i][k])) return 0;
        for (int k = 0; k < 3; ++k) if (fabsf(local[i][k * 4 + 3]) > 500) return 0;
    }
    return 1;
}
static float dot(const float* a, const float* b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
static void cross(const float* a, const float* b, float* out) {
    float r[3] = {a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]};
    memcpy(out, r, sizeof(r));
}
static void normalize(float* v) {
    float length = sqrtf(dot(v, v));
    if (length > 1e-9f) { v[0] /= length; v[1] /= length; v[2] /= length; } else v[0] = v[1] = v[2] = 0;
}
static void column0(const float* m, float* out) { out[0] = m[0]; out[1] = m[3]; out[2] = m[6]; }

/* Shortest rotation taking unit vector a onto unit vector b. */
static void arc(const float* a, const float* b, float* out) {
    float v[3], c = dot(a, b);
    cross(a, b, v);
    if (c < -0.999999f) {
        float axis[3], helper[3] = {fabsf(a[0]) < .9f ? 1.f : 0, fabsf(a[0]) < .9f ? 0 : 1.f, 0};
        cross(a, helper, axis); normalize(axis);
        for (int r = 0; r < 3; ++r) for (int k = 0; k < 3; ++k) out[r * 3 + k] = 2 * axis[r] * axis[k] - (r == k);
        return;
    }
    float k = 1 / (1 + c);
    float skew[9] = {0, -v[2], v[1], v[2], 0, -v[0], -v[1], v[0], 0}, skew2[9];
    mul(skew, skew, skew2);
    for (int i = 0; i < 9; ++i) out[i] = (i % 4 == 0) + skew[i] + skew2[i] * k;
}
/* Rig (x, y, z-up) -> Gothic (x, y-up, z): swap y and z. */
static void gothic_vector(const float* v, float* out) { float r[3] = {v[0], v[2], v[1]}; memcpy(out, r, sizeof(r)); }
static void gothic_rotation(const float* r, float* out) {
    static const int swap[3] = {0, 2, 1};
    float g[9];
    for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j) g[i * 3 + j] = r[swap[i] * 3 + swap[j]];
    memcpy(out, g, sizeof(g));
}
/* The rig's T-pose faces -Z (Gothic); Gothic's model faces +Z. */
static void ry180(const float* m, float* out) {
    for (int j = 0; j < 3; ++j) { out[j] = -m[j]; out[3 + j] = m[3 + j]; out[6 + j] = -m[6 + j]; }
}

static int find(int count, const char* const* names, const char* name) {
    for (int i = 0; i < count; ++i) if (!strcmp(names[i], name)) return i;
    return -1;
}

int retarget_setup(RetargetSetup* s, int count, const char* const* names, const int* parent, const float (*local)[16]) {
    memset(s, 0, sizeof(*s));
    if (count < 1 || count > RETARGET_MAX_NODES) return 0;
    s->count = count;
    float bind_p[RETARGET_MAX_NODES][3];
    for (int i = 0; i < count; ++i) {
        s->parent[i] = parent[i];
        if (parent[i] >= i) return 0; /* parents must come first */
        const float* m = local[i];
        float r[9] = {m[0], m[1], m[2], m[4], m[5], m[6], m[8], m[9], m[10]};
        memcpy(s->local_r[i], r, sizeof(r));
        s->local_p[i][0] = m[3]; s->local_p[i][1] = m[7]; s->local_p[i][2] = m[11];
        if (parent[i] < 0) { memcpy(s->bind_r[i], r, sizeof(r)); memcpy(bind_p[i], s->local_p[i], 12); }
        else {
            mul(s->bind_r[parent[i]], r, s->bind_r[i]);
            mul_vec(s->bind_r[parent[i]], s->local_p[i], bind_p[i]);
            for (int k = 0; k < 3; ++k) bind_p[i][k] += bind_p[parent[i]][k];
        }
        s->joint[i] = s->child[i] = s->spine_slot[i] = -1;
    }
    for (unsigned m = 0; m < sizeof(MAPPING) / sizeof(MAPPING[0]); ++m) {
        int i = find(count, names, MAPPING[m].name);
        if (i < 0) return 0;
        s->joint[i] = MAPPING[m].joint; s->child[i] = MAPPING[m].child;
        if (MAPPING[m].child < 0) { memcpy(s->reference_r[i], s->bind_r[i], sizeof(s->bind_r[i])); continue; }
        /* Reference: the bind bone swung onto the rig's T-pose direction. */
        float rig_dir[3], direction[3], bone[3], swing[9];
        for (int k = 0; k < 3; ++k) rig_dir[k] = rig_bind_pos[MAPPING[m].child][k] - rig_bind_pos[MAPPING[m].joint][k];
        normalize(rig_dir);
        gothic_vector(rig_dir, direction);
        direction[0] = -direction[0]; direction[2] = -direction[2]; /* RY180 */
        column0(s->bind_r[i], bone); normalize(bone);
        arc(bone, direction, swing);
        mul(swing, s->bind_r[i], s->reference_r[i]);
    }
    int chain[5];
    for (int k = 0; k < 5; ++k) if ((chain[k] = find(count, names, SPINE_CHAIN[k])) < 0) return 0;
    float length[5] = {0};
    for (int k = 1; k < 5; ++k) length[k] = length[k - 1] + sqrtf(dot(s->local_p[chain[k]], s->local_p[chain[k]]));
    for (int k = 0; k < 4; ++k) { s->spine_slot[chain[k]] = k; s->spine_fraction[k] = length[k + 1] / length[4]; }
    s->pelvis = chain[0];
    for (int l = 0; l < 2; ++l) for (int k = 0; k < 3; ++k) if ((s->legs[l][k] = find(count, names, LEG_NAMES[l][k])) < 0) return 0;
    s->ready = 1;
    return 1;
}

void retarget_pose(const RetargetSetup* s, const float (*pose)[13], const float* marvin_r, const float* marvin_p, const float* ride_origin, float (*out_local)[16]) {
    float inv_marvin[9], g_r[RETARGET_MAX_NODES][9], g_p[RETARGET_MAX_NODES][3];
    transpose(marvin_r, inv_marvin);
    /* Both positions must share the worker's fixed ride frame. Subtract the
       origin from the vob first to avoid adding large world offsets to every
       joint (and losing their sub-centimetre detail). */
    float rider_in_frame[3];
    for (int k = 0; k < 3; ++k) rider_in_frame[k] = marvin_p[k] - ride_origin[k];
#define MODEL_POINT(bone, out) do { float w_[3]; gothic_vector(&pose[bone][9], w_); \
        for (int k_ = 0; k_ < 3; ++k_) w_[k_] = w_[k_] * 100 - rider_in_frame[k_]; mul_vec(inv_marvin, w_, out); } while (0)

    /* Rig spine curve in model space with cumulative lengths. */
    float curve[5][3], curve_length[5] = {0}, spine_target[4][3];
    for (int k = 0; k < 5; ++k) MODEL_POINT(RIG_SPINE[k], curve[k]);
    for (int k = 1; k < 5; ++k) {
        float d[3] = {curve[k][0] - curve[k - 1][0], curve[k][1] - curve[k - 1][1], curve[k][2] - curve[k - 1][2]};
        curve_length[k] = curve_length[k - 1] + sqrtf(dot(d, d));
    }
    for (int slot = 0; slot < 4; ++slot) {
        float target = s->spine_fraction[slot] * curve_length[4];
        for (int k = 1; k < 5; ++k) {
            if (target <= curve_length[k] || k == 4) {
                float span = curve_length[k] - curve_length[k - 1];
                float t = span > 1e-6f ? (target - curve_length[k - 1]) / span : 0;
                for (int a = 0; a < 3; ++a) spine_target[slot][a] = curve[k - 1][a] + (curve[k][a] - curve[k - 1][a]) * t;
                break;
            }
        }
    }

    for (int i = 0; i < s->count; ++i) {
        int p = s->parent[i];
        if (p < 0) {
            memcpy(g_r[i], s->bind_r[i], sizeof(g_r[i]));
            float pelvis_target[3], offset[3];
            MODEL_POINT(1, pelvis_target);
            mul_vec(g_r[i], s->local_p[s->pelvis], offset);
            for (int k = 0; k < 3; ++k) g_p[i][k] = pelvis_target[k] - offset[k];
            continue;
        }
        float offset[3];
        mul_vec(g_r[p], s->local_p[i], offset);
        for (int k = 0; k < 3; ++k) g_p[i][k] = g_p[p][k] + offset[k];
        if (s->joint[i] < 0) { mul(g_r[p], s->local_r[i], g_r[i]); continue; }
        int joint = s->joint[i], child = s->child[i];
        float rig_r[9], bind_t[9], delta_w[9], delta[9], placed[9], candidate[9];
        memcpy(rig_r, pose[joint], sizeof(rig_r));
        transpose(rig_bind_rot[joint], bind_t);
        mul(rig_r, bind_t, delta_w);
        gothic_rotation(delta_w, delta);
        ry180(s->reference_r[i], placed);
        mul(delta, placed, candidate);
        mul(inv_marvin, candidate, candidate);
        float want[3];
        int aim = 0;
        if (s->spine_slot[i] >= 0) {
            for (int k = 0; k < 3; ++k) want[k] = spine_target[s->spine_slot[i]][k] - g_p[i][k];
            normalize(want); aim = 1;
        } else if (child >= 0) {
            float d[3] = {pose[child][9] - pose[joint][9], pose[child][10] - pose[joint][10], pose[child][11] - pose[joint][11]}, g[3];
            gothic_vector(d, g);
            mul_vec(inv_marvin, g, want);
            normalize(want); aim = 1;
        }
        if (aim && dot(want, want) > .5f) {
            float bone[3], swing[9];
            column0(candidate, bone); normalize(bone);
            arc(bone, want, swing);
            mul(swing, candidate, candidate);
        }
        memcpy(g_r[i], candidate, sizeof(candidate));
    }

    /* Two-bone leg IK onto the rig's foot targets with Gothic's segment lengths. */
    for (int l = 0; l < 2; ++l) {
        int a = s->legs[l][0], b = s->legs[l][1], c = s->legs[l][2];
        float l1 = sqrtf(dot(s->local_p[b], s->local_p[b])), l2 = sqrtf(dot(s->local_p[c], s->local_p[c]));
        float hip[3], target[3], delta[3], hint[3];
        memcpy(hip, g_p[a], sizeof(hip));
        MODEL_POINT(LEG_RIG[l][0], target);
        for (int k = 0; k < 3; ++k) delta[k] = target[k] - hip[k];
        float distance = sqrtf(dot(delta, delta));
        if (distance < 1e-3f) continue;
        float axis[3] = {delta[0] / distance, delta[1] / distance, delta[2] / distance};
        float d = fminf(fmaxf(distance, fabsf(l1 - l2) + 1e-3f), l1 + l2 - 1e-3f);
        float projection = (l1 * l1 - l2 * l2 + d * d) / (2 * d);
        float height = sqrtf(fmaxf(l1 * l1 - projection * projection, 0));
        MODEL_POINT(LEG_RIG[l][1], hint);
        for (int k = 0; k < 3; ++k) hint[k] -= hip[k];
        float along = dot(hint, axis), bend[3] = {hint[0] - axis[0] * along, hint[1] - axis[1] * along, hint[2] - axis[2] * along};
        normalize(bend);
        if (dot(bend, bend) < .5f) { float x[3] = {1, 0, 0}; cross(axis, x, bend); normalize(bend); }
        float knee[3], ankle[3];
        for (int k = 0; k < 3; ++k) { knee[k] = hip[k] + axis[k] * projection + bend[k] * height; ankle[k] = hip[k] + axis[k] * d; }
        const float* starts[2] = {hip, knee};
        const float* ends[2] = {knee, ankle};
        int bones[2] = {a, b};
        for (int n = 0; n < 2; ++n) {
            float bone[3], want[3] = {ends[n][0] - starts[n][0], ends[n][1] - starts[n][1], ends[n][2] - starts[n][2]}, swing[9];
            column0(g_r[bones[n]], bone); normalize(bone); normalize(want);
            arc(bone, want, swing);
            mul(swing, g_r[bones[n]], g_r[bones[n]]);
        }
        memcpy(g_p[b], knee, sizeof(knee));
        memcpy(g_p[c], ankle, sizeof(ankle));
    }
    /* Re-derive every unmapped node (toes, fingers, slots) from its parent. */
    for (int i = 0; i < s->count; ++i) {
        int p = s->parent[i];
        if (p < 0 || s->joint[i] >= 0) continue;
        float offset[3];
        mul(g_r[p], s->local_r[i], g_r[i]);
        mul_vec(g_r[p], s->local_p[i], offset);
        for (int k = 0; k < 3; ++k) g_p[i][k] = g_p[p][k] + offset[k];
    }
    /* Node-local trafos as Gothic stores them. */
    for (int i = 0; i < s->count; ++i) {
        int p = s->parent[i];
        float r[9], t[3];
        if (p < 0) { memcpy(r, g_r[i], sizeof(r)); memcpy(t, g_p[i], sizeof(t)); }
        else {
            float inv[9], d[3] = {g_p[i][0] - g_p[p][0], g_p[i][1] - g_p[p][1], g_p[i][2] - g_p[p][2]};
            transpose(g_r[p], inv);
            mul(inv, g_r[i], r);
            mul_vec(inv, d, t);
        }
        float* m = out_local[i];
        m[0] = r[0]; m[1] = r[1]; m[2] = r[2]; m[3] = t[0];
        m[4] = r[3]; m[5] = r[4]; m[6] = r[5]; m[7] = t[1];
        m[8] = r[6]; m[9] = r[7]; m[10] = r[8]; m[11] = t[2];
        m[12] = m[13] = m[14] = 0; m[15] = 1;
    }
#undef MODEL_POINT
}
